# DK FSS.  Frederikshavn - Skagen (smalspor)
#
let fs = path("d3.dk.fss");

with detail = 4, railway = :first :g1000 :pax :removed {
    with link = "line.dk.FSS" {
        track(
                fs[:fre.xs - 1.1mo, :fre.xs - 1mo] >> 1mo
            ..  fs[:fre.zs + 2mo, :fre.zs + 2.11km]
        );
        line_label(:left:ne, fs[:fre.zs + 2.1km] << 0.5lt, "FSS");
        track(fs[:fre.zs + 2.09km, :ell - 0.49sw]);
    }

    with link = "point.dk.Elling-FSJ", railway = :station {
        track(fs[:ell - 0.5sw, :ell + 0.5sw]);
        marker(:left :de.hp, fs[:ell] << 0.5lt);
        station(:left, fs[:ell] << 0.5mt << 1sh + (-2.3dt, 2dt),
            "Elling", "FFS: 5,3"
        );
    }

    with link = "line.dk.FSS" {
        track(fs[:ell + 0.49sw, :rim - 0.49sw]);
    }

    with link = "point.dk.Rimmen-FSJ", railway = :station {
        track(fs[:rim - 0.5sw, :rim + 0.5sw]);
        marker(:left :de.hp, fs[:rim] << 0.5lt);
        station(:left, fs[:rim] << 0.5mt << 1sh + (-1.7dt, 1.7dt),
            "Rimmen", "FFS: ??"
        );
    }

    with link = "line.dk.FSS" {
        track(fs[:rim + 0.5sw, :jer.yf]);
    }
}

